CREATE TABLE rp_world_chapters (chapter_run_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,guild_id BIGINT UNSIGNED NOT NULL,chapter_key VARCHAR(64) NOT NULL,status VARCHAR(24) NOT NULL,current_stage_key VARCHAR(64) NOT NULL,started_at VARCHAR(64) NOT NULL,stage_started_at VARCHAR(64) NOT NULL,deadline_at VARCHAR(64) NOT NULL,updated_at VARCHAR(64) NOT NULL,resolved_at VARCHAR(64) NULL,ending_key VARCHAR(64) NULL,resolution_snapshot_json LONGTEXT NOT NULL,PRIMARY KEY(chapter_run_id),KEY idx_chapter(guild_id,status)) ENGINE=InnoDB;
CREATE TABLE rp_world_causality_signals (signal_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,guild_id BIGINT UNSIGNED NOT NULL,domain VARCHAR(32) NOT NULL,units INT NOT NULL,occurred_at VARCHAR(64) NOT NULL,PRIMARY KEY(signal_id)) ENGINE=InnoDB;
CREATE TABLE player_scenario_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,guild_id BIGINT UNSIGNED NOT NULL,domain VARCHAR(64) NOT NULL,completed_at VARCHAR(64) NULL,PRIMARY KEY(id)) ENGINE=InnoDB;
CREATE TABLE rp_world_community_project_outcomes (outcome_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,guild_id BIGINT UNSIGNED NOT NULL,result_status VARCHAR(24) NOT NULL,branch_key VARCHAR(64) NOT NULL,career_units INT NOT NULL,business_units INT NOT NULL,recorded_at VARCHAR(64) NOT NULL,PRIMARY KEY(outcome_id)) ENGINE=InnoDB;
CREATE TABLE contracts (contract_id BIGINT UNSIGNED NOT NULL,guild_id BIGINT UNSIGNED NOT NULL,status VARCHAR(16) NOT NULL,resolved_at VARCHAR(64) NULL,PRIMARY KEY(contract_id)) ENGINE=InnoDB;
CREATE TABLE contract_objectives (objective_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,contract_id BIGINT UNSIGNED NOT NULL,guild_id BIGINT UNSIGNED NOT NULL,objective_type VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL,PRIMARY KEY(objective_id)) ENGINE=InnoDB;
CREATE TABLE character_memory_state (memory_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,guild_id BIGINT UNSIGNED NOT NULL,category VARCHAR(24) NOT NULL,active TINYINT NOT NULL,occurred_at VARCHAR(64) NOT NULL,PRIMARY KEY(memory_id)) ENGINE=InnoDB;
